public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // check input validity
    if (start == null || start.length != 2 || end == null || end.length != 2 || paths == null || paths.length < 1) {
        throw new IllegalArgumentException("Invalid input");
    }
    // find starting and ending node IDs
    int startNodeId = findNode(start[0], start[1], n);
    int endNodeId = findNode(end[0], end[1], n);
    // check if start and end nodes are connected
    for (int i = 0; i < paths.length; i++) {
        if (paths[i][0] == startNodeId && paths[i][1] == endNodeId) {
            return "can be travelled";
        }
    }
    return "cannot be travelled";
}

private int findNode(int x, int y, int n) {
    // assuming nodes are fixed on a grid
    return n * y + x;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || start.length != 2 || end == null || end.length != 2 || paths == null || paths.length != n - 1) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Initialize the maze as a 2D array of boolean values to track visited nodes
    boolean[][] maze = new boolean[n][n];
    for (boolean[] row : maze) {
        Arrays.fill(row, false);
    }

    // Set the starting node to visited
    maze[start[0]][start[1]] = true;

    // Queue to store the next exploration steps
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[]{start[0], start[1]});

    // Define the directions (north, south, east, west)
    int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    // Perform BFS
    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        // Check if the current node is the ending node
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Explore the neighboring cells
        for (int[] direction : directions) {
            int x = current[0] + direction[0];
            int y = current[1] + direction[1];

            // Check if the neighboring cell is within bounds and not visited
            if (x >= 0 && x < n && y >= 0 && y < n && !maze[x][y]) {
                // Mark the neighbor as visited
                maze[x][y] = true;
                // Add the neighbor to the queue
                queue.offer(new int[]{x, y});
            }
        }
    }

    // If no valid path is found after exploring all possible directions
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        int startX = start[0], startY = start[1];
        int endX = end[0], endY = end[1];

        // Initialize a set to keep track of visited nodes
        Set<String> visited = new HashSet<>();

        // Initialize a stack to perform depth-first search
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{startX, startY});

        while (!stack.isEmpty()) {
            int[] current = stack.pop();

            // Check if the current node is the end node
            if (current[0] == endX && current[1] == endY) {
                return "can be travelled";
            }

            // Mark the current node as visited
            visited.add(current[0] + "," + current[1]);

            // Explore all adjacent nodes
            for (int i = 0; i < paths.length; i++) {
                int nextX = current[0] + paths[i][0];
                int nextY = current[1] + paths[i][1];

                // Check if the next node is within the bounds and not visited
                if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited.contains(nextX + "," + nextY)) {
                    stack.push(new int[]{nextX, nextY});
                }
            }
        }

        return "cannot be travelled";
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if n is valid
    if (n <= 0) {
        return "invalid input";
    }

    // Check if start and end are within the valid range
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || 
        end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "invalid input";
    }

    // Convert start and end coordinates to 1D index
    int startIdx = start[0] * n + start[1];
    int endIdx = end[0] * n + end[1];

    // Create a visited array to keep track of visited nodes
    boolean[] visited = new boolean[n * n];
    visited[startIdx] = true;

    // Use a queue to perform breadth-first search (BFS)
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(startIdx);

    // Perform BFS
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endIdx) {
            return "can be travelled";
        }
        int[] dir = {0, 1, 0, -1, 0};
        for (int i = 0; i < 4; i++) {
            int nx = current / n + dir[i];
            int ny = current % n + dir[i + 1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx * n + ny] && 
                pathExists(n, start, end, paths, nx, ny, visited)) {
                visited[nx * n + ny] = true;
                queue.offer(nx * n + ny);
            }
        }
    }
    return "cannot be travelled";
}

private static boolean pathExists(int n, int[] start, int[] end, int[][] paths, int x, int y, boolean[] visited) {
    if (x == end[0] && y == end[1]) {
        return true;
    }
    for (int[] path : paths) {
        int[] neighbor = {x + path[0], y + path[1]};
        if (neighbor[0] >= 0 && neighbor[0] < n && neighbor[1] >= 0 && neighbor[1] < n && !visited[neighbor[0] * n + neighbor[1]]) {
            return pathExists(n, start, end, paths, neighbor[0], neighbor[1], visited);
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Mark the starting node as visited
    visited[start[0]] = true;

    // Function to perform a DFS to check if the end is reachable
    boolean isReachable = isReachable(paths, start[0], end[0], visited);

    // Return the result based on whether the end is reachable
    return isReachable ? "can be travelled" : "cannot be travelled";
}

private static boolean isReachable(int[][] paths, int curr, int target, boolean[] visited) {
    // If the current node is the target, return true
    if (curr == target) return true;

    // If the current node is already visited or out of bounds, return false
    if (visited[curr] || curr < 0 || curr >= paths.length) return false;

    // Mark the current node as visited
    visited[curr] = true;

    // Recursively check for reachable nodes in all paths from the current node
    for (int[] path : paths[curr]) {
        if (isReachable(paths, path[0], target, visited)) return true;
    }

    // If no reachable node is found, return false
    return false;
}

public static String appx(String word1, String word2) {
    int commonChars = IntStream.range(0, Math.min(word1.length(), word2.length()))
                              .filter(i -> word1.charAt(i) == word2.charAt(i))
                              .count();
    int totalChars = word1.length() + word2.length();
    int gcd = gcd(commonChars, totalChars);
    int reducedCommonChars = commonChars / gcd;
    int reducedTotalChars = totalChars / gcd;

    return String.format("appx(%s, %s) = %d/%d", word1, word2, reducedCommonChars, reducedTotalChars);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String appx(String word1, String word2) {

