                    intersections++;
                }
            }
        }

        if (totalLength == 0) {
            throw new IllegalArgumentException("Both words are empty");
        }

        int gcd = gcd(intersections, totalLength);
        return "appx(" + word1 + ", " + word2 + ") = " + (intersections / gcd) + "/" + (totalLength / gcd);
    }

private static int gcd(int a, int b) {
