public static String appx(String word1, String word2) {
    int commonChars = 0;
    for (char ch : word1.toCharArray()) {
        if (word2.indexOf(ch) != -1) {
            commonChars++;
        }
    }

    if (commonChars == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int totalChars = word1.length() + word2.length();
    return "appx(" + word1 + ", " + word2 + ") = " + commonChars + "/" + totalChars;
}

public static String appx(String word1, String word2) {
    if (word1.length() == 0 || word2.length() == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int commonCount = 0;

    for (char c1 : word1.toCharArray()) {
        for (char c2 : word2.toCharArray()) {
            if (c1 == c2) {
                commonCount++;
            }
        }
    }

    int numerator = commonCount;
    int denominator = word1.length() + word2.length();

    // Find the greatest common divisor (GCD) of numerator and denominator
    int gcd = findGCD(numerator, denominator);

    // Simplify the fraction by dividing both numerator and denominator by GCD
    numerator /= gcd;
    denominator /= gcd;

    // Format the result as a reduced fraction
    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

private static int findGCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

