    java.util.stream.IntStream
        .filter(x -> x != 0)
        .sorted()
        .limit(arr.length * 0.05)
        .mapToDouble(x -> x)
        .average()
        .orElse(0.0);
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int size = arr.length;
    Arrays.sort(arr);

    double totalSum = 0.0;
    for (int i = size * 5 / 100; i < size - size * 5 / 100; i++) {
        totalSum += arr[i];
    }

    return totalSum / (size - size * 2 / 100);
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);
    // Calculate the number of elements to remove (5% of the total)
    int n = arr.length;
    int removeCount = (int) Math.ceil(n * 0.05);
    // Rearrange the array to remove the smallest 5% and largest 5%
    int[] trimmedArr = Arrays.copyOfRange(arr, removeCount, arr.length - removeCount);
    // Calculate the sum of the remaining elements
    double sum = 0;
    for (int num : trimmedArr) {
        sum += num;
    }
    // Calculate the mean with an error within 10^-5
    return sum / (trimmedArr.length);
}

public double trimMean(int[] arr) {
  Arrays.sort(arr);
  int start = (int) Math.floor(((double) arr.length) * 0.05);
  int end = arr.length - start - 1;
  int sum = 0;

  for (int i = start; i <= end; i++) {
    sum += arr[i];
  }

  return (double) sum / (arr.length - 2 * start);
}

public boolean canArrange(int[] arr, int k) {
  // Check for invalid input: k must be a non-zero positive integer
  if (k == 0 || k <= 0) {
    throw new IllegalArgumentException("k must be a non-zero positive integer");
  }

  // Filter out pairs whose sums are not divisible by k
  Map<Integer, Integer> remainderCount = new HashMap<>();
  for (int num : arr) {
    int remainder = num % k;
    remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
  }

  // Check if it's possible to pair elements such that the total sum is divisible by k
  boolean possible = true;
  for (int remainder : remainderCount.keySet()) {
    if (remainder % 2 == 1 && remainder != 0) {
      possible = false; // More than one odd remainder, cannot pair all elements
      break;
    }
  }

  return possible;
}

public boolean canArrange(int[] arr, int k) {
    // Count the frequency of each remainder when divided by k
    int[] remainders = new int[k];
    for (int num : arr) {
        remainders[num % k]++;
    }

    // Check if it's possible to pair the numbers
    int pairsCount = arr.length / 2;

    // Iterate through the remainders
    for (int i = 0; i < k / 2; i++) {
        int remainder = k - i;
        if (remainder < k / 2) { // Current remainder pair with the complement remainder
            if (remainders[i] != remainders[remainder]) {
                continue;
            }
            if (remainders[i] % 2 == 1) {
                // Only odd remainder can pair with its complement in odd number of pairs
                continue;
            }
        } else {
            // Remaining remainder pair with the complement remainder
            if (remainders[i] != remainders[k - i]) {
                continue;
            }
        }

        pairsCount -= 2; // Subtract the number of pairs formed pair
        if (pairsCount < 0) {
            return false; // Not enough numbers to form more pairs
        }
    }

    return pairsCount == 0; // Check if all numbers can be paired
}

public boolean canArrange(int[] arr, int k) {
    int len = arr.length;
    if (len % 2 != 0) {
        return false;
    }
    Map<Integer, Integer> counts = new HashMap<>();
    for (int num : arr) {
        int mod = num % k;
        if (mod == 0) {
            counts.put(mod, counts.getOrDefault(mod, 0) + 1);
        } else {
            int target = k - mod;
            counts.put(target, counts.getOrDefault(target, 0) + 1);
        }
    }
    boolean isValid = true;
    for (int key : counts.keySet()) {
        if (key != 0 && counts.containsKey(key) && counts.get(key) != counts.get(k - key)) {
            isValid = false;
            break;
        }
    }
    return isValid;
}

public boolean canArrange(int[] arr, int k) {
    boolean[] modCt = new boolean[k];
    for (int num : arr) {
        int mod = num % k;
        if (mod == 0) {
            modCt[0]++; // Increment count for numbers divisible by k
        } else {
            int complement = k - mod;
            if (complement < modCt.length) {
                modCt[complement]++; // Increment count for the complement
            } else if (k - modCt.length == k - mod) {
                return false; // Check for odd count of numbers with the complement when k mod num is k mod k
            }
        }
    }
    for (int count : modCt) {
        if (count % 2 != 0) {
            return false; // If any count is odd, it's not possible to form pairs of equal sums
        }
    }
    return true; // If all counts are even, it's possible to form pairs of equal sums
}

public boolean canArrange(int[] arr, int k) {
    int[] frequency = new int[k];
    for (int num : arr) {
        if (num % k == 0) {
            frequency[0]++;
        } else {
            frequency[num % k]++;
        }
    }
    for (int i = 1; i < k / 2; i++) {
        if (frequency[i] != frequency[k - i]) {
            return false;
        }
    }
    return true;
}

public static int minTime(int n, int[][] edges, boolean[] hasApple) {
        if (n == 0) {
            return 0;
        }

        // Build the graph using adjacent list
        HashMap<Integer, ArrayList<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            graph.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
            graph.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
        }

        // Depth-first search to collect apples and return time
        return dfs(0, -1, graph, hasApple);
    }

private static int dfs(int node, int parent, HashMap<Integer, ArrayList<Integer>> graph, boolean[] hasApple) {
        int time = 0;
        HashSet<Integer> visited = new HashSet<>();

        for (int neighbor : graph.get(node)) {
            if (neighbor == parent) {
                continue;
            }
            visited.add(neighbor);
            time += dfs(neighbor, node, graph, hasApple);
        }

        if (!visited.isEmpty() || hasApple[node]) {
            return time + 2; // Time taken to move from parent to node and back
        }
        return time; // No apples in the subtree
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
