            graph.putIfAbsent(edge[1], new ArrayList<>());
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        // Helper function to calculate the time to collect apples
        return dfs(0, -1, graph, hasApple);
    }

private int dfs(int node, int parent, Map<Integer, List<Integer>> graph, boolean[] hasApple) {
        int time = 0;

        // Iterate through all neighbors
        for (int neighbor : graph.getOrDefault(node, new ArrayList<>())) {
            if (neighbor != parent) {
                int childTime = dfs(neighbor, node, graph, hasApple);
                if (childTime > 0 || hasApple[neighbor]) {
                    time += 2 + childTime; // +2 for the time to traverse between parent and child, + childTime for time to collect apples
                }
            }
        }

        return time;
    }

