private int minTime(int n, int[][] edges, boolean[] hasApple, int currentNode) {
        List<Integer> children = new ArrayList<>();
        for (var edge : edges) if (edge[0] == currentNode) children.add(edge[1]);
        if (children.isEmpty()) return 0;

        boolean hasAnApple = hasApple[currentNode] || children.stream().anyMatch(hasApple::get);

        int additionalTime = hasAnApple ? 2 : 0;
        int totalTime = additionalTime;
        for (var child : children) totalTime += minTime(n, edges, hasApple, child);
        return totalTime;
