public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int root = 0; // Assuming root node is node 0
    Apple[] apple = new Apple[n];
    apple[root].reachable = true; // Root node is reachable from itself
    apple[root].hasApple = true; // Root node has an apple

    // Create a deep copy of hasApple array to keep track of reachable apple nodes
    boolean[] reachableApple = new boolean[n];
    System.arraycopy(hasApple, 0, reachableApple, 0, n);

    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            Apple tempApple = apple[i];
            tempApple.reachable = true;
            apple[tempApple.reachable] = tempApple;
        }
    }

    return dfs(apple, root, -1);
}

public int dfs(Apple[] apple, int u, int parent) {
    if (u == root) {
        return 0;
    }

    int sum = 0;
    for (int v : graph.get(u)) {
        if (v == parent) {
            continue;
        }
        sum += dfs(apple, v, u);
    }

    // Check if the current node has an apple or any child can reach an apple with an apple in a subtree
    if (hasApple[u] || (apple[u].reachable && apple[u].has apple)) {
        return sum + 2;
    }

    return sum;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Build an adjacency list for graph
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (!graph.containsKey(u)) {
                graph.put(u, new ArrayList<>());
            }
            if (!graph.containsKey(v)) {
                graph.put(v, new ArrayList<>());
            }
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        // DFS to find the minimum time required
        return DFS(0, graph, hasApple, new HashSet<>()) + hasApple[0];
    }

private int DFS(int cur, Map<Integer, List<Integer>> graph, boolean[] hasApple, Set<Integer> visited) {
        visited.add(cur);
        int totalTime = 0;
        for (int neighbor : graph.get(cur)) {
            if (!visited.contains(neighbor)) {
                totalTime += DFS(neighbor, graph, hasApple, visited);
            }
        }
        if ((totalTime > 0 || hasApple[cur]) && !neighbor.isEmpty()) {
            totalTime += 2;
        }
        return totalTime;
    }

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    List<Character> remainingChars = new ArrayList<>();
    String uniqueChars = s.chars()
                                     .mapToObj(c -> (char) c)
                                     .collect(Collectors.toSet())
                                     .stream()
                                     .collect(Collectors.toList());
    Collections.sort(uniqueChars);

    while (uniqueChars.size() > 0) {
        for (char c : uniqueChars) {
            result.append(c);
            remainingChars.remove(c);
        }

        Collections.sort(remainingChars, Collections.reverseOrder());
        if (remainingChars.size() > 0) {
            for (char c : remainingChars) {
                result.append(c);
                remainingChars.remove(c);
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    // Special case handle
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Character frequency counting
    int[] charCount = new int[256];
    for (char c : s.toCharArray()) {
        charCount[c]++;
    }

    // Result StringBuilder
    StringBuilder result = new StringBuilder();

    // Loop until all characters are picked
    int i = 1, j = 255;
    while (result.length() < s.length()) {
        // Add smallest characters (from `i` to `j`) to the result
        for (int c = i; c <= j; c++) {
            if (charCount[c] > 0) {
                result.append((char) c);
                charCount[c]--;
            }
            if (result.length() == s.length()) {
                break;
            }
        }
        // Add largest characters (from `j` to `i`) to the result
        for (int c = j; c >= i; c--) {
            if (charCount[c] > 0) {
                result.append((char) c);
                charCount[c]--;
            }
            if (result.length() == s.length()) {
                break;
            }
        }
        i += 2;
        j -= 2;
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    int[] charCount = new int[26]; // To count occurrences of each character
    int lastChar = -1; // To keep track of the last character appended
    int length = s.length();

    // Count occurrences of each character
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    // Sort characters in ascending order for picking numbers
    Arrays.sort(charCount);

    while (result.length() < length) {
        // Add smallest characters
        for (int i = 0; i < 26 && result.length() < length; i++) {
            if (charCount[i] > 0) {
                result.append((char) (i + 'a'));
                charCount[i]--;
                lastChar = i;
            }
        }

        // Add largest characters
        for (int i = 25; i >= 0 && result.length() < length; i--) {
            if (charCount[i] > 0) {
                result.append((char) (i + 'a'));
                charCount[i]--;
                lastChar = i;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }

        Queue<Character> minHeap = new PriorityQueue<>();
        Queue<Character> maxHeap = new PriorityQueue<>((o1, o2) -> o2 - o1);
        TreeMap<Character, Integer> countMap = new TreeMap<>();

        // Count the frequency of each character
        for (char c : s.toCharArray()) {
            countMap.put(c, countMap.getOrDefault(c, 0) + 1);
            minHeap.offer(c);
        }
        maxHeap.addAll(countMap.keySet());

        StringBuilder result = new StringBuilder();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            // Process the result until it is full
            if (result.length() == n) {
                break;
            }

            // If there are minimums left, add them
            while (!minHeap.isEmpty()) {
                char minChar = minHeap.poll();
                if (countMap.get(minChar) == 1) {
                    result.append(minChar);
                    countMap.remove(minChar);
                } else {
                    result.append(minChar);
                    countMap.put(minChar, countMap.get(minChar) - 1);
                    break;
                }
            }

            // If there are maximums left, add them
            while (!maxHeap.isEmpty()) {
                char maxChar = maxHeap.poll();
                if (countMap.get(maxChar) == 1) {
                    result.append(maxChar);
                    countMap.remove(maxChar);
                } else {
                    result.append(maxChar);
                    countMap.put(maxChar, countMap.get(maxChar) - 1);
                    break;
                }
            }
        }

        return result.toString();
    }

public static String sortString(String s) {
        PriorityQueue<Character> minHeap = new PriorityQueue<>((a, b) -> a - b);
        PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        // Populate the heaps
        for (char c : s.toCharArray()) {
            minHeap.offer(c);
            maxHeap.offer(c);
        }

        StringBuilder sortedS = new StringBuilder();
        while (!minHeap.isEmpty()) {
            // Append the smallest character
            sortedS.append(minHeap.poll());
            if (!minHeap.isEmpty()) {
                // Append the smallest greater character
                sortedS.append(minHeap.poll());
            }
        }

        while (!maxHeap.isEmpty()) {
            // Append the largest character
            sortedS.append(maxHeap.poll());
            if (!maxHeap.isEmpty()) {
                // Append the largest smaller character
                sortedS.append(maxHeap.poll());
            }
        }

        return sortedS.toString();
    }

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length <= 1) return false;

    int total = 0;
    for (int num : nums) total += num;

    int smallest = 0;
    int highest = total;
    while (smallest < highest) {
        int mid = (smallest + highest) / 2;
        if (canSplitMid(nums, mid)) {
            highest = mid;
        } else {
            smallest = mid + 1;
        }
    }

    return smallest == highest;
}

private boolean canSplitMid(int[] nums, int mid) {
    int max = Arrays.stream(nums).max().getAsInt();

    int count = 1;
    int sum = 0;
    for (int num : nums) {
        sum += num;
        if (sum >= mid * count) return true;
        max -= num;
        count++;
        if (max <= 0) return false;
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the total sum of the integers in the array
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // Check if the total sum is divisible by n (since the average must be an integer)
    if (totalSum % n != 0) {
        return false;
    }

    // Calculate the target sum for each part of the array
    int targetSum = totalSum / n;

    // Initialize a variable to keep track of the cumulative sum so far
    int cumulativeSum = 0;

    // Try to find a subarray with a sum equal to the target sum
    for (int i = 0; i < n; i++) {
        cumulativeSum += nums[i];
        if (cumulativeSum == targetSum) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length <= 1) return false;

    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    int targetSum = totalSum / 2;

    int[] prefixSum = new int[nums.length];
    prefixSum[0] = nums[0];
    for (int i = 1; i < nums.length; i++) {
        prefixSum[i] = prefixSum[i - 1] + nums[i];
    }

    // Check if there is any prefix sum that equals half of the total sum
    return prefixSum[prefixSum.length - 1] == targetSum;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of all elements and the length of the array
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int len = nums.length;

    // Initialize the sum for the first half of the array
    int targetSum1 = totalSum / 2;

    // Sort the array to facilitate partitioning
    Arrays.sort(nums);

    // Iterate through the array to find a valid partition
    for (int i = 0; i < len - 1; i++) {
        // Calculate the sum of the remaining elements
        int remainingSum = targetSum1 - nums[i];
        // Check if the remaining sum can be found in the second half of the array
        int left = i + 1;
        int right = len - 1;
        while (left < right) {
            int sum = nums[left] + nums[right];
            if (sum == remainingSum) {
                return true;
            } else if (sum < remainingSum) {
                left++;
            } else {
                right--;
            }
        }
    }

    // If no valid partition is found, return false
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Array cannot be null or empty");
    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }

    int[] dp = new int[n + 1];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i-1];
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 1) return cost[0]; // If there's only one step, the bottom step's cost is the answer.

    int[] dp = new int[n+1];
    dp[0] = cost[0]; // Cost to reach the first step is the same as the cost of that step.
    dp[1] = cost[1]; // Cost to reach the second step is the sum of the first and second step costs.

    for(int i=2; i<=n; ++i){
        // Minimum cost to reach the current step is the minimum of the cost to reach the previous step and the cost to reach the two steps before, plus the cost of the current step.
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
    }
    return dp[n]; // The minimum cost to reach the top of the floor is the minimum of the cost to reach the last two steps, which is the answer.
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);


    int[] dp = new int[n+1];
    dp[1] = cost[0];
    dp[2] = cost[1];

    for (int i = 3; i <= n; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i-1];
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i-1], dp[i-2]);
    }

    return Math.min(dp[n-1], dp[n-2]);
}

