public boolean hasAllCodes(String s, int k) {
    // Check edge cases quickly
    if (s == null || k * k > s.length()) {
        return false;
    }

    boolean[] marks = new boolean[1 << k]; // We use bitwise operations

    // Iterate through all possible substrings of length k in s
    for (int checked = 0; checked < s.length() - k + 1; checked++) {
        String subStr = s.substring(checked, checked + k);
        if (marks[Integer.parseInt(subStr, 2)]) {
            return false; // Another substring exists for the same mask
        }
        // Mark this mask as checked
        marks[Integer.parseInt(subStr, 2)] = true;
    }

    // If no duplicates were found, all substrings are valid
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int length = s.length(), count = (1 << k) - 1;
    Set<String> set = new HashSet<>();

    for (int i = 0; i <= length - k; i++) {
        // Ensure string is exactly k bits long
        String sub = s.substring(i, i + k);
        if (sub.length() != k) return false;
        set.add(sub);
    }

    // Check each generated substring against our set
    while (set.size() < count) {
        String s1 = "", s2 = "";
        for (int i = 0; i < k; i++) {
            // Create new next string by inserting a 0 and 1 to each possible slot
            s1 = s1 + "0";
            s2 = s2 + "1";
            int index1 = (i & 1) == 0 ? 0 : i + 1;
            int index2 = (i & 1) == 0 ? i + 1 : 0;
            s1 += s.substring(index1);
            s2 += s.substring(index2);
        }
        set.add(s1);
        set.add(s2);
    }

    return set.size() == count;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        throw new IllegalArgumentException("Invalid input");
    }
    // Create a boolean array of size 1<<k to check if all possible k-bit strings
    boolean[] allCodes = new boolean[(1 << k)];
    for (int i = 0; i < (1 << k); i++) {
        int num = i;
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < k; j++) {
            sb.append(num % 2);
            num >>= 1;
        }
        String binaryString = sb.toString();
        allCodes[i] = s.contains(binaryString);
    }
    // Check if all possible k-bit strings are present in the string
    for (boolean flag : allCodes) {
        if (!flag) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        throw new IllegalArgumentException("Invalid input.");
    }

    if (k >= s.length()) {
        return false;
    }

    boolean[] seen = new boolean[1 << k];
    for (int i = 0; i <= s.length() - k; i++) {
        StringBuilder substring = new StringBuilder(s, i, k);
        int substringInt = Integer.parseInt(substring.toString(), 2);
        if (!seen[substringInt]) {
            seen[substringInt] = true;
        }
    }
    for (boolean bit : seen) {
        if (!bit) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        throw new IllegalArgumentException("Input string or k should not be null or zero");
    }

    int strLen = s.length();
    Set<String> allCodes = new HashSet<>();

    for (int i = 0; i <= strLen - k; i++) {
        String substring = s.substring(i, i + k);
        if (allCodes.contains(substring)) {
            return false;
        }
        allCodes.add(substring);
    }

    return allCodes.size() == (int) Math.pow(2, k);
}

