public int minInsertions(String s) {
    int left = 0, right = 0;
    int result = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            left++;
        } else {  // s.charAt(i) is ')'
            right++;
            if (right > left) {  // need to insert '(' at the beginning
                right--;
                left++;
                result++;
            }
        }
    }

    // If there are still unmatched right brackets at the end, all of them need to be inserted at the end
    int rightFinal = left - right;
    result += rightFinal;

    return result;
}

public int minInsertions(String s) {
    // Count the number of unmatched '('
    int unmatchedLeft = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            unmatchedLeft++;
        } else {
            // If the previous character is ')', decrement unmatched '('
            if (unmatchedLeft > 0) {
                unmatchedLeft--;
            } else {
                // If there are no unmatched '(' before the current ')', increment insertions
                unmatchedLeft = 1;
            }
        }
    }

    // The minimum number of insertions required
    int insertions = unmatchedLeft;

    // If there are still unmatched ')' after processing the entire string, increment insertions
    if (unmatchedLeft > 0) {
        insertions += unmatchedLeft;
    }

    return insertions;
}

