public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else {
            balance--;
        }
        if (balance < 0) {
            insertions++;
            balance = -1; // reset to at least 0
        }
    }
    // If there are任意多余的右括号，所有多余的右括号需要在最左边补齐，需要在string的前面增加多余的括号的个数
    insertions += balance;
    return insertions;
}

public int minInsertions(String s) {
    int openCount = 0; // Tracks the number of opening brackets.
    int insertCount = 0; // Tracks the number of left bracket insertions needed.

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            openCount++;
        } else { // c == ')'
            if (openCount == 0) {
                insertCount++; // Need to insert '(' to balance.
            } else {
                openCount--; // Reduce the opening bracket count.
            }
        }
    }

    // The remaining '(' are needed at the end.
    insertCount += openCount;

    return insertCount;
}

