public int findMinFibonacciNumbers(int k) {
    int[] fib = {1, 1};
    while (fib[fib.length - 1] < k) {
        fib = new int[fib.length + 1];
        fib[fib.length - 2] = fib[fib.length - 1] + fib[fib.length - 2];
    }
    int count = 0;
    for (int i = fib.length - 2; i >= 0; i--) {
        while (k >= fib[i]) {
            k -= fib[i];
            count++;
        }
    }
    return count;
}

