        fibs.add(fibs.get(i - 1) + fibs.get(i - 2));
    }
    int minFibs = Integer.MAX_VALUE;
    List<Integer> current = new ArrayList<>();
    generateFibonacci(k, minFibs, current);
    return Math.min(minFibs, current.size());
}

private void generateFibonacci(int k, int minFibs, List<Integer> current) {
    if (k == 0) {
        if (current.size() < minFibs) {
            minFibs = current.size();
        }
        return;
    }
    if (k < fibs.get(fibs.size() - 1)) {
        return;
    }
    current.add(fibs.get(fibs.size() - 1));
    generateFibonacci(k - fibs.get(fibs.size() - 1), minFibs, current);
    current.remove(current.size() - 1);
    generateFibonacci(k, minFibs, current);
}

public int findMinFibonacciNumbers(int k) {
