    fibonacci.add(2);
    while (true) {
        int next = fibonacci.get(fibonacci.size() - 1) + fibonacci.get(fibonacci.size() - 2);
        if (next > k) {
            break;
        }
        fibonacci.add(next);
    }

    int count = 0;
    while (k > 0) {
        for (int i = fibonacci.size() - 1; i >= 0; i--) {
            if (fibonacci.get(i) <= k) {
                k -= fibonacci.get(i);
                count++;
                break;
            }
        }
    }

    return count;
}

