    fibList.add(1); // Initialize the first two Fibonacci numbers
    fibList.add(1);

    // Generate Fibonacci numbers until the list exceeds k
    while (fibList.get(fibList.size() - 1) < k) {
        fibList.add(fibList.get(fibList.size() - 1) + fibList.get(fibList.size() - 2));
    }

    int result = 0; // Variable to store the count of Fibonacci numbers used
    // Traverse the list backwards to find the minimum number of Fibonacci numbers that sum up to k
    for (int i = fibList.size() - 1; i >= 0 && k > 0; i--) {
        if (k >= fibList.get(i)) {
            k -= fibList.get(i); // Subtract the Fibonacci number from k
            result++; // Increment the count of Fibonacci numbers used
        }
    }

    return result; // Return the minimum count of Fibonacci numbers that sum up to k
}

