public String makeGood(String s) {
        // Initialize a StringBuilder to efficiently build the result string
        StringBuilder sb = new StringBuilder();
        // Iterate through each character in the input string
        for (char c : s.toCharArray()) {
            // Check if the last character in the result string is the same but with different case
            if (!sb.isEmpty() && (sb.charAt(sb.length() - 1) == c ^ (c - 'a') == 32)) {
                // If true, remove the last character from the result string
                sb.deleteCharAt(sb.length() - 1);
            } else {
                // If false, add the current character to the result string
                sb.append(c);
            }
        }
        // Return the final "good" string
        return sb.toString();
    }

public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    int i = 0;
    while (i < s.length() - 1) {
        if (Character.compare(s.charAt(i), Character.toUpperCase(s.charAt(i + 1))) == 0 ||
            Character.compare(s.charAt(i), Character.toLowerCase(s.charAt(i + 1))) == 0) {
            s = s.substring(0, i) + s.substring(i + 2);
        } else {
            i++;
        }
    }

    return s;
}

public String makeGood(String s) {
    Deque<Character> stack = new LinkedList<>();
    for (char c : s.toCharArray()) {
        if (!stack.isEmpty() && Math.abs(stack.peek() - c) == 32) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }
    return new String(stack.toArray(new char[0]));
}

