        } else {
            stack.push(c);
        }
    }
    StringBuilder result = new StringBuilder();
    while (!stack.isEmpty()) {
        result.append(stack.pop());
    }
    return result.reverse().toString();
}

public int maxUniqueSplit(String s) {
    int maxLength = 0;
    Set<String> set = new HashSet<>();
    int start = 0;

    while (start < s.length()) {
        for (int i = start; i < s.length(); i++) {
            if (set.contains(s.substring(start, i + 1))) {
                maxLength = Math.max(maxLength, set.size());
                start = i + 1;
                set.clear();
                break;
            }
            set.add(s.substring(start, i + 1));
        }
    }

    return Math.max(maxLength, set.size());
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    Set<String> uniqueSubstrings = new HashSet<>();
    for (int i = 0; i <= s.length(); i++) {
        for (int j = i + 1; j <= s.length() + 1; j++) {
            String currentSubstring = s.substring(i, j);
            if (!uniqueSubstrings.contains(currentSubstring)) {
                uniqueSubstrings.add(currentSubstring);
                if (canReconstruct(s, uniqueSubstrings)) {
                    return uniqueSubstrings.size();
                }
                uniqueSubstrings.remove(currentSubstring);
            }
        }
    }
    return 0;
}

private boolean canReconstruct(String original, Set<String> substringSet) {
    Set<Character> uniqueChars = new HashSet<>();
    for (String substring : substringSet) {
        for (char c : substring.toCharArray()) {
            uniqueChars.add(c);
        }
    }

    if (uniqueChars.size() != original.length()) {
        return false;
    }

    StringBuilder reconstructedString = new StringBuilder();
    for (char c : original.toCharArray()) {
        if (uniqueChars.contains(c)) {
            reconstructedString.append(c);
            uniqueChars.remove(c);
        }
    }

    return reconstructedString.toString().equals(original);
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    if (n >= 32) return n; // Since each character can be split in one way, at most 31 unique splits.

    int[] sum = new int[26 * 26];
    int unique = 0;

    for (int i = 0; i < n; i++) {
        int mask = 0;
        for (int j = i; j < n; j++) {
            mask |= 1 << ('z' - s.charAt(j));
            if (sum[mask] == 0) {
                unique++;
                sum[mask] = 1;
            }
        }
    }

    return unique;
}

