private int dfs(String s, int index, Set<String> current, int count) {
    if (index == s.length()) {
        return count + 1;
    }

    for (int end = index; end <= s.length(); end++) {
        String currentSubstring = s.substring(index, end);
        if (!current.contains(currentSubstring)) {
            current.add(currentSubstring);
            count = dfs(s, end + 1, current, count);
            current.remove(currentSubstring);
        }
    }

    return count;
}

