        } else if (!"..".equals(log) && !"./".equals(log)) {
            operationCount++;
        }
    }
    return operationCount;
}

public int minOperations(String[] logs) throws IllegalArgumentException {
    int steps = 0;
    for (String log : logs) {
        if (log.equals("../")) {
            if (steps > 0) steps--;
        } else if (!log.equals("./")) {
            steps++;
        }
    }
    if (steps < 0) steps = 0;
    return steps;
}

public String getSmallestString(int n, int k) {
    if (n == 0) {
        return "";
    }
    StringBuilder res = new StringBuilder();
    for (int i = 0; i < n; i++) {
        while (k >= 26) {
            res.append('z');
            k -= 26;
        }
        res.append((char) (k + 'a' - 1));
        k = 0;
    }
    return res.toString();
}

public String getSmallestString(int n, int k) {
    char[] charArray = new char[n];
    for (int i = 0; i < n; i++) {
        while (true) {
            charArray[i] = (char) ('a' + (k % 26)); // Get the current character
            k = (k - (charArray[i] - 'a')) / 26; // Reduce the value by the position of the character
            if (k >= 1) break; // If the value is still positive, we can continue
            charArray[i] = 'z'; // If the value is zero, set it to 'z'
            k--; // Reduce the value by one
        }
    }
    return new String(charArray);
}

public String getSmallestString(int n, int k) {
    // Initialize an array to store the characters of the result
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        // Calculate the value of the character 'a' + i
        int value = i + 1;
        // Determine how many of the next characters can be 'a'
        int nextChars = (k - value) / (n - i - 1);
        // Update k by subtracting the number of next characters times their value
        k -= nextChars * (n - i - 1);
        // Set the character at position i to 'a' + nextChars
        result[i] = 'a' + nextChars;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int remainder = k % 26;
        sb.insert(0, (char) ('a' + remainder));
        k = (k - remainder) / 26;
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    // Initialize the result string with a-z
    StringBuilder result = new StringBuilder(new String("a".repeat(n)));

    // Calculate the position of the first character that needs to be adjusted
    int positionToAdjust = (k - 1) % 26;

    // Adjust the first character to the highest possible value
    result.setCharAt(0, (char) (result.charAt(0) + ((int) positionToAdjust + 1)));

    // Adjust the other characters if necessary
    for (int i = 1; i < n; i++) {
        if (result.charAt(i) - result.charAt(i - 1) >= 26) {
            result.setCharAt(i, 'a');
            result.setCharAt(i - 1, (char)(((int) result.charAt(i) - (int) result.charAt(i - 1) - 26) + 96));
        } else {
            result.setCharAt(i, (char)(result.charAt(i) + positionToAdjust + 1));
        }
    }

    return result.toString();
}

public static double calculateProbability(int n) {
    if (n <= 2) {
        return 1.0;
    }
    double[] dp = new double[n + 1];
    dp[1] = 1.0;
    dp[2] = 0.5;
    for (int i = 3; i <= n; i++) {
        dp[i] = dp[i - 1] / 2 + dp[i - 2] / 2;
    }
    return dp[n];
}

public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0;
    }
    double[][] dp = new double[n+1][2];
    for (int i = 0; i <= n; i++) {
        dp[i][0] = 0.5; // seat on one side
        dp[i][1] = i == 1 ? 1 : 0.0; // seat on other side
    }
    for (int i = 2; i <= n; i++) {
        double temp0 = dp[i-1][0];
        double temp1 = dp[i-1][1];
        dp[i][0] = (temp0 + temp1) * 0.5;
        dp[i][1] = (temp0 + temp1) * 0.5;
    }
    return dp[n][0];
}

public static double calculateProbability(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    if (n == 1) {
        return 1.0;
    }
    // Calculate the probability using the recursive formula involving binomial distributions
    return 1.0 - binomialCoefficient(n, 1) / binomialCoefficient(n, n);
}

private static double binomialCoefficient(int n, int k) {
    if (k > n - k) {
        k = n - k;
    }
    double result = 1.0;
    for (int i = 0; i < k; i++) {
        result *= n - i;
        result /= i + 1;
    }
    return result;
}

public static double calculateProbability(int n) {
    // Check for invalid input
    if (n <= 0) {
        throw new IllegalArgumentException("Number of passengers must be a positive integer");
    }

    // Base cases: 1 passenger or 2 passengers
    if (n == 1) {
        return 1.0;
    }
    if (n == 2) {
        return 0.5;
    }

    // Initialize the probability with the base cases
    double probability = 1.0 / n;

    // Compute the probability for n > 2 using the recurrence relation
    for (int i = 3; i <= n; i++) {
        probability = (2.0 * probability) / (i + 1);
    }

    return probability;
}

public static double calculateProbability(int n) {
    if (n <= 1) {
        throw new IllegalArgumentException("n must be greater than 1");
    }
    if (n == 2) {
        return 0.5;
    }

    double probability = 1.0;
    for (int i = 3; i <= n; i++) {
        probability += (i - 1) * 0.5 / probability;
    }

    return probability;
}

