public static int singleNumber(int[] nums) {
    int count[] = new int[32]; // Tracking the count of bits for each position
    int result = 0; // Result variable to store the final single number

    // Count the occurrences of each bit position for all elements in the array
    for (int num : nums) {
        int temp = num;
        for (int i = 0; i < 32; i++) {
            if ((temp & 1) == 1) {
                count[i]++;
            }
            temp >>= 1;
        }
    }

    // Reconstruct the single number from the counts of its bits
    for (int i = 0; i < 32; i++) {
        if (count[i] % 3 != 0) {
            result |= (1 << i); // Set the bit at the current position
        }
    }

    return result;
}

public static int singleNumber(int[] nums) {
    // Handle null inputs or separate them with a check
    if (nums == null || nums.length <= 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }

    // Use a Hash Set to track occurrences of each element
    Set<Integer> set = new HashSet<>();

    // Iterate through the array
    for (int num : nums) {
        // If element is already in the set, remove it
        if (!set.contains(num)) {
            set.add(num);
        } else {
            // If element is found again, remove it from the set
            set.remove(num);
        }
    }

    // The remaining element in the set is the single occurrence
    return set.iterator().next();
}

