public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        Queue<Integer> queue = new LinkedList<>();
        set.add(0);
        set.add(1);

        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current >= low && current <= high) {
                result.add(current);
            }
            if (current % 10 != 0 && !set.contains(current - 1)) {
                set.add(current - 1);
                queue.add(current - 1);
            }
            if (current % 10 != 9 && !set.contains(current + 1)) {
                set.add(current + 1);
                queue.add(current + 1);
            }
        }
        Collections.sort(result);
        return result;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        if (low > high) {
            return steppingNumbers;
        }

        Queue<Integer> queue = new Queue<>();
        queue.add(0);
        queue.add(1);

        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                steppingNumbers.add(num);
            }

            for (int i = 0; i <= 1; i++) {
                int next = num * 10 + i;
                if (next >= low && next <= high && !steppingNumbers.contains(next)) {
                    queue.add(next);
                }
            }
        }

        steppingNumbers.sort(Integer::compare);
        return steppingNumbers;
    }

public static int countDigitOne(int n) {
    int count = 0;
