    for (int i = 1; i <= n; i++) {
        count += (i / (int) Math.pow(10, Math.floor(Math.log10(i))) - (i / (int) Math.pow(10, Math.floor(Math.log10(i - 1)))) * 10;
        int digitAtIndex = i % (int) Math.pow(10, Math.floor(Math.log10(i))) % 10;
        if (digitAtIndex == 1) count += (i % (int) Math.pow(10, Math.floor(Math.log10(i))) - i % (int) Math.pow(10, Math.floor(Math.log10(i - 1))) + 1;
    }
    return count;
