}

private static int countOccurrences(int number, int digit) {
    if (number == 0) return 0;
    int factor = 1, count = 0;
    while (number > 0) {
        int temp = number % 10;
        count += (temp == digit) ? factor : 0;
        number /= 10;
        factor *= 10;
    }
    return count;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }

    int count = 0;
    int place = 1;

    while (n > 0) {
        int digit = n % 10;
        n /= 10;

        if (digit == 1) {
            count += n * place + place;
        } else if (digit > 1) {
            count += ((n + 1) * place);
        }

        place *= 10;
    }

    return count;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative.");
    }

    if (n == 0) {
        return 0;
    }

    int count = 0;
    int order = 1;
    int high = n / order;
    int low = n % order;

    if (high > 0) {
        count += (high * order); // Count for high order digits
    }

    count += countDigits_lessThan(high + 1, order); // Count for low order digits up to the high order digit
    count += low + (high > 0 ? 1 : 0); // Count for the '1' at the bottom of the number

    return count;
}

private static int countDigits_lessThan(int n, int order) {
    if (n < order) {
        return n;
    }

    return n / order + countDigits_lessThan(n % order, order);
}

