public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;

    int maxLen = 0;
    int rows = mat.length;
    int cols = mat[0].length;
    int[][] direction = {
        {0, 1}, {1, 1}, {1, 0}, {1, -1}
    };

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                for (int k = 0; k < direction.length; k++) {
                    int len = 1;
                    int x = i + direction[k][0];
                    int y = j + direction[k][1];
                    while (x >= 0 && y >= 0 && x < rows && y < cols && mat[x][y] == 1) {
                        len++;
                        x += direction[k][0];
                        y += direction[k][1];
                    }
                    maxLen = Math.max(maxLen, len);
                }
            }
        }
    }

    return maxLen;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int maxLen = 0;
    int m = mat.length;
    int n = mat[0].length;

    // Check horizontally
    for (int i = 0; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (mat[i][j] == 0 || mat[i][j-1] == 0) {
                maxLen = Math.max(maxLen, 0);
            } else {
                maxLen = Math.max(maxLen, j);
            }
        }
    }

    // Check vertically
    for (int j = 0; j < n; j++) {
        for (int i = 1; i < m; i++) {
            if (mat[i][j] == 0 || mat[i-1][j] == 0) {
                maxLen = Math.max(maxLen, 0);
            } else {
                maxLen = Math.max(maxLen, i);
            }
        }
    }

    // Check diagonally
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (mat[i][j] == 0 || (mat[i-1][j-1] == 0 && mat[i-1][j] == 0)) {
                maxLen = Math.max(maxLen, 0);
            } else {
                maxLen = Math.max(maxLen, i + j);
            }
        }
    }

    // Check anti-diagonally
    for (int i = 0; i < min(m, n); i++) {
        for (int j = 0; j <= m - 1 - i; j++) {
            if (mat[i][j] == 0 || (mat[i+1][j+1] == 0 && mat[i+1][j] == 0)) {
                maxLen = Math.max(maxLen, 0);
            } else {
                maxLen = Math.max(maxLen, m - 1 - i - j);
            }
        }
    }

    return maxLen;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 1;
    int[][] horizontals = new int[rows][cols];
    int[][] verticals = new int[rows][cols];
    int[][] diagonals = new int[rows][cols];
    int[][] antiDiagonals = new int[rows][cols];

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            lengthToRight(mat, r, c, horizontals);
            lengthBelow(mat, r, c, verticals);
            lengthBelowDiagonal(mat, r, c, diagonals);
            lengthBelowAntiDiagonal(mat, r, c, antiDiagonals);
            maxLength = Math.max(maxLength, Math.max(
                Math.max(Math.max(horizontals[r][c], verticals[r][c]), diagonals[r][c]), 
                antiDiagonals[r][c]));
        }
    }

    return maxLength;
}

