    for (int col = 0; col < colLen; col++) {
        dp[0][col] = mat[0][col];
        maxLength = Math.max(maxLength, dp[0][col]);
    }

    // Fill cells for vertical lines
    for (int row = 0; row < rowLen; row++) {
        dp[row][0] = mat[row][0];
        maxLength = Math.max(maxLength, dp[row][0]);
    }

    // Fill cells for diagonal lines
    for (int i = 1; i < rowLen; i++) {
        for (int j = 1; j < colLen; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = Math.max(dp[i - 1][j - 1] + 1, Math.max(dp[i - 1][j] + 1, dp[i][j - 1] + 1, 1));
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    // Fill cells for anti-diagonal lines
    for (int i = 0; i < rowLen; i++) {
        for (int j = i; j < colLen; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = Math.max(dp[i - 1][j + 1] + 1, Math.max(dp[i - 1][j] + 1, dp[i][j + 1] + 1, 1));
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    return maxLength;
}

