public static int squarePermutations(int[] A) {
        Set<Integer> numbers = new HashSet<>();
        int res = 0;

        // Extract unique elements from array
        for (int n : A) {
            numbers.add(n);
        }

        // Check if each unique element is a perfect square
        for (int com : numbers) {
            if (!isPerfectSquare(com)) {
                return res;
            }
        }

        // Generate permutations and count square permutations
        int[] freq = new int[numbers.size()];
        for (int num : A) {
            freq[num]++;
        }

        increment(res, 1, freq);

        return res / 2;
    }

private static void increment(int[] res, int c, int[] freq) {
        if (c == freq.length) {
            return;
        }

        for (int i = 0; i < freq.length; i++) {
            if (freq[i] > 0) {
                freq[i]--;
                increment(res, c + 1, freq);
                freq[i]++;
            }
        }
    }

