            } else {
                return 0;
            }
        }

        Map<String, Integer> memo = new HashMap<>();
        return helper(A, new HashSet<>(), 0, memo);
    }

private int helper(int[] A, Set<Integer> used, int index, Map<String, Integer> memo) {
        if (index == A.length) {
            return 1;
        }
        if (memo.containsKey(index)) {
            return memo.get(index);
        }

        int count = 0;
        for (int i = 0; i < A.length; i++) {
            if (!used.contains(i) && isSquare(A[index] + A[i])) {
                used.add(i);
                count += helper(A, used, index + 1, memo);
                used.remove(i);
            }
        }

        memo.put(index, count);
        return count;
    }

