private static int squarePermutations(int[] A, int start) {
        if (start == A.length - 1) {
            return A[start] % 100 == 0;
        }

        int count = 0;
        for (int i = start; i < A.length; i++) {
            swap(A, start, i);
            if (isPerfectSquare(sum(A, start))) {
                if (start + 1 == A.length - 1) {
                    count++;
                } else {
                    count += squarePermutations(A, start + 1);
                }
            }
            swap(A, start, i);
        }
        return count;
    }

private static void swap(int[] A, int i, int j) {
        int temp = A[i];
        A[i] = A[j];
        A[j] = temp;
    }

