        return true;
    }

private static int countPermutations(int[] A, int start, int permCount) {
        if (start == A.length) {
            return 1;
        }
        int result = 0;
        for (int i = start; i < A.length; i++) {
            if (start == 0 || (A[start - 1] <= A[i] && Math.abs(A[start - 1] - A[i]) == A[i] - A[i - 1])) {
                swap(A, start, i);
                result += countPermutations(A, start + 1, permCount + 1);
                swap(A, start, i); // backtrack
            }
        }
        return result;
    }

private static void swap(int[] A, int i, int j) {
        int temp = A[i];
        A[i] = A[j];
        A[j] = temp;
    }

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) return 0;

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    Stack<Integer> stack = new Stack<>();

    // Fill the left array
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            left[i] = -1;
        } else {
            left[i] = stack.peek();
        }
        stack.push(i);
    }

    // Clear the stack for next phase
    stack.clear();

    // Fill the right array
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            right[i] = n;
        } else {
            right[i] = stack.peek();
        }
        stack.push(i);
    }

    // Calculate the area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        maxArea = Math.max(maxArea, heights[i] * width);
    }

    return maxArea;
}

