    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    List<int[]> diags = new ArrayList<>();
    for (int r = 0; r < mat.length; r++) {
        for (int c = 0; c < mat[r].length; c++) {
            diags.add(new int[]{r, c});
        }
    }
    Collections.sort(diags, Comparator.comparingInt(o -> o[0] + o[1]));
    int[] out = new int[mat.length * mat[0].length];
    int pointer = 0;
    for (int[] diag : diags) {
        for (int r = diag[0] - 1, c = diag[1]; r >= 0 && c >= 0; r--, c--) {
            out[pointer++] = mat[r][c];
        }
        for (int r = diag[0], c = diag[1] + 1; r < mat.length && c < mat[r].length; r++, c++) {
            out[pointer++] = mat[r][c];
        }
    }
    return out;
}

public int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[][] dirs = {{0, 1}, {1, 0}};
    int [] result = new int[rows * cols];
    int idx = 0, currentDir = 0;
    int currentRow = 0, currentCol = 0;

    while (idx < result.length) {
        result[idx++] = mat[currentRow][currentCol];
        int nextRow = currentRow + dirs[currentDir][0];
        int nextCol = currentCol + dirs[currentDir][1];
        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
            currentDir = (currentDir + 1) % 2;
            currentRow += dirs[currentDir][0];
            currentCol += dirs[currentDir][1];
        } else {
            currentRow = nextRow;
            currentCol = nextCol;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
