        throw new IllegalArgumentException("Input matrix cannot be null or empty");
    }

    int rows = mat.length, cols = mat[0].length;
    int[] result = new int[rows * cols];
    int topRow = 0, topCol = 0, bottomRow = rows - 1, bottomCol = cols - 1;
    boolean goingUp = true;

    while(topRow <= bottomRow && topCol <= bottomCol) {
        if(goingUp) {
            for(int i = topRow, j = topCol; i <= bottomRow && j <= bottomCol; i++, j++) {
                result[index++] = mat[i][j];
            }
            topRow++;
        } else {
            for(int i = topRow, j = bottomCol; i <= bottomRow && j >= topCol; i++, j--) {
                result[index++] = mat[i][j];
            }
            bottomCol--;
        }
        goingUp = !goingUp;
    }

    return result;
}

public static int findSmallestInteger(int n) {
    // Separate digits of n
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }
    Collections.sort(digits, Collections.reverseOrder());

    // Iterate through all permutations
    for (int i = 0; i < digits.size(); i++) {
        int[] perm = digits.stream()
                .mapToInt(Integer::intValue)
                .toArray();
        // Swap i-th and last non-zero digit
        int j = digits.indexOf(Collections.max(perm));
        if (j != Collections.size() - 1) {
            int temp = perm[i];
            perm[i] = perm[j];
            perm[j] = temp;
            // Form the smallest permutation
            int smallest = 0;
            for (int x : perm) {
                smallest = smallest * 10 + x;
            }
            return smallest;
        }
    }
    // Return -1 if no valid permutation is found
    return -1;
}

