public static boolean isBoomerang(int[][] points) {
    if (points.length != 3 || (points[0][0] == points[1][0] && points[1][0] == points[2][0] || 
        points[0][1] == points[1][1] && points[1][1] == points[2][1])) {
        throw new IllegalArgumentException("The input points do not form a valid boomerang.");
    }

    // Calculate the slope of the line segments
    double slope1 = (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
    double slope2 = (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);

    // Check if the points are collinear
    if (slope1 == slope2) {
        throw new IllegalArgumentException("The input points form a line and are not collinear.");
    }

    // Calculate the expected slope for a boomerang
    double expectedSlope = ((points[1][0] - points[0][0]) * (points[2][1] - points[0][1])) 
                            / ((points[2][0] - points[0][0]) * (points[1][0] - points[0][0]));

    // Determine if the points form a boomerang
    return slope1 != expectedSlope && slope2 != expectedSlope;
}

