}

public static boolean isCollinear(int[] p1, int[] p2, int[] p3) {
    // Calculate the determinant of the matrix formed by the points
    int det = p1[0] * (p2[1] - p3[1]) + p2[0] * (p3[1] - p1[1]) + p3[0] * (p1[1] - p2[1]);

    // If the determinant is not zero, points are collinear
    return det == 0;
}

