    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(start)) {
            currentLength++;
        } else {
            start = i;
            currentLength = 1;
        }
        maxLength = Math.max(maxLength, currentLength);
    }

