public static int calculateEnergy(String s) {
    int n = s.length();
    if (n <= 1) {
        return 0; // If the string is empty or contains only one character, energy is 0.
    }

    int maxLength = 0;
    int currentLength = 1;
    char previousChar = s.charAt(0);

    for (int i = 1; i < n; i++) {
        if (s.charAt(i) == previousChar) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
            previousChar = s.charAt(i);
        }
    }

    maxLength = Math.max(maxLength, currentLength); // Check the last substring.

    // Adjusting energy for cases where energy can be reduced further,
    // e.g., if there are multiple, alternating characters that don't count.
    int adjustedEnergy = maxLength - 1; // Subtract 1 for the initial value.
    return adjustedEnergy;
}

