        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    int maxEnergy = 1; // Minimum non-empty substring with 1 character is of length 1
    int currentLength = 1; // Length of the current non-empty substring with 1 character
    int longestLength = 1; // Longest non-empty substring with 1 character encountered

    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        char prevChar = s.charAt(i - 1);

        if (c == prevChar) {
            currentLength++;
            longestLength = Math.max(longestLength, currentLength);
        } else {
            currentLength = 1;
        }

        maxEnergy = Math.max(maxEnergy, longestLength);
    }

    return maxEnergy;
}

