public static List<Integer> lexicalOrder(int n) {
        if (n <= 0) {
            return Collections.emptyList();
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            search(result, i, n);
        }
        return result;
    }

private static void search(List<Integer> result, int start, int _max) {
        if (start >= _max) {
            return;
        }
        result.add(start);
        for (int i = 0; i <= 9; i++) {
            int next = start * 10 + i;
            if (next > _max) {
                break;
            }
            search(result, next, _max);
        }
    }

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        generateLexicalOrder(1, n, result);
        return result;
    }

private static void generateLexicalOrder(int current, int end, List<Integer> result) {
        if (current > end) return;
        result.add(current);

        if (current * 10 <= end) {
            generateLexicalOrder(current * 10, end, result);
        }

        if (current + 1 <= end) {
            generateLexicalOrder(current + 1, end, result);
        }
    }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n == 0) return result;

    functionCall(result, n, 0, 0);
    return result;
}

private static void functionCall(List<Integer> result, int n, int curr, int floor) {
    // If the current number exceeds n, return
    if (curr > n) return;
    // Add the current number to the result list
    result.add(curr);
    // Create the next floor by multiplying the current number by 10
    int nextFloor = curr * 10;
    // Explore the first child of the current floor
    functionCall(result, n, nextFloor, floor);
    // If the next floor does not exceed n, create the second child of the current floor
    if (nextFloor < n && floor > 0) {
        functionCall(result, n, nextFloor + 1, floor);
    }
}

