        List<Integer> ans = new ArrayList<>();
        if (n == 0 || n == 1) {
            return ans;
        }
        for (int i = 1; i <= 9; i++) {
            dfs(i, n, ans);
        }
        return ans;
    }

private void dfs(int i, int n, List<Integer> ans) {
        if (i > n) {
            return;
        }
        ans.add(i);
        for (int j = 0; j <= 9; j++) {
            dfs(i * 10 + j, n, ans);
        }
    }

