public static int minPerfectSquareSum(int n) {
    int sum = 0;
    if (n < 1) {
        throw new IllegalArgumentException("Input should be a positive integer.");
    }
    for (int i = 1; sum + i * i <= n; i++) {
        sum += i * i;
        if (sum == n) {
            return i;
        }
    }
    return -1; // If no perfect square numbers are found, return -1
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) throw new IllegalArgumentException("Input must be a positive integer");

    // Use dynamic programming to find the minimum number of perfect squares
    int[] dp = new int[n + 1];
    dp[0] = 0; // Base case: 0 perfect squares required to sum to 0

    for (int i = 1; i <= n; ++i) {
        dp[i] = Integer.MAX_VALUE; // Initialize maximum possible value
        for (int j = 1; j * j <= i; ++j) {
            dp[i] = Math.min(dp[i], 1 + dp[i - j * j]); // Update dp[i] with the minimum value
        }
    }

    return dp[n]; // The result is in dp[n]
}

