public static String reverseWords(String s) {
    // Check for empty string
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Split the string into words using space as the delimiter
    String[] words = s.split(" ");

    // Reverse each word and concatenate them back
    StringBuilder reversed = new StringBuilder();
    for (String word : words) {
        char[] charArray = word.toCharArray();
        int start = 0;
        int end = charArray.length - 1;
        while (start < end) {
            char temp = charArray[start];
            charArray[start] = charArray[end];
            charArray[end] = temp;
            start++;
            end--;
        }
        reversed.append(String.valueOf(charArray));
        reversed.append(" ");
    }

    // Remove the trailing space
    return reversed.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split("\\s+"); // split the string by one or more spaces
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        if (word != null && !word.isEmpty()) {
            StringBuilder reversed = new StringBuilder(word);
            reversed.reverse(); // reverse the characters of the word
            result.append(reversed).append(" "); // append the reversed word followed by a space
        }
    }

    return result.toString().trim(); // remove the trailing space and return the result
}
